mapper.update:
update cash_service_points
set grid_code = #{gridCode},
    grid_name = #{gridName}
where id=#{id}

mapper.select:
select csp.id, csp.serve_bank, csp.serve_anchor, csp.serve_anchor_addr, csp.service_type, csp.serve_point_name, csp.serve_point_addr, csp.chosen_position, csp.duty_name, csp.duty_phone, csp.constructing_mode, csp.constructing_case, csp.start_time, csp.service_mode, csp.publishing_device, csp.grid_code, csp.grid_name, csp.created_time, csp.updated_time from cash_service_points csp left join pa_addr_info_type pait on csp.grid_code = pait.code
and serve_anchor like concat('%', #{serveAnchor}, '%')
and service_type = #{serviceType}
and serve_point_name like concat('%', #{servePointName}, '%')
and constructing_mode = #{constructingMode}
and constructing_case = #{constructingCase}
and (
pait.ancestor_codes like concat('%,', #{item}, ',%')
)

select csp.serve_bank, csp.serve_anchor, csp.serve_anchor_addr, csp.service_type, csp.serve_point_name, csp.serve_point_addr, csp.chosen_position, csp.duty_name, csp.duty_phone, csp.constructing_mode, case csp.constructing_case when 1 then '洽谈中' when 2 then '建设中' when 3 then '运行中' end as constructingCase, csp.start_time, csp.service_mode, csp.publishing_device, csp.grid_name, csp.exchange_money_count, csp.exchange_money_number, csp.money_total, csp.lqb_money_total, csp.strokes_total, csp.lqb_strokes_total, csp.money_total_accumulative, csp.lqb_money_total_accumulative, csp.scrapped_conversion_money, csp.a_scrapped_conversion_money, csp.remark from cash_service_points csp left join pa_addr_info_type pait on csp.grid_code = pait.code
and serve_anchor like concat('%', #{serveAnchor}, '%')
and service_type = #{serviceType}
and serve_point_name like concat('%', #{servePointName}, '%')
and constructing_mode = #{constructingMode}
and constructing_case = #{constructingCase}
and (
pait.ancestor_codes like concat('%,', #{item}, ',%')
)
